import {trackFolder,newTrackId,validTrackId,serverConfig} from './mod-identity.js?v=20261007-return';
import {exportImages} from './tracer-ui.js?v=20261007-return';
import {DEFAULT_EXPORT,validateExport,exportServerZip} from './ac-export.js?v=20261007-return';
import {GRASS} from './scenery.js?v=20261007-return';
const $=s=>document.querySelector(s);
export function mountACSetup(api){const section=$('.export-settings'),body=section.querySelector('.details-body');
 const inputs=Object.fromEntries(['author','country','city','pits','kerbs','barriers','ai'].map(k=>[k,$('#export-'+k)]));
 body.innerHTML=`<div class="ac-package-banner"><span>CONTENT MANAGER / TRACK PACKAGE</span><b id="ac-folder"></b><small id="ac-package-summary"></small></div><div class="ac-presets" role="group" aria-label="Mod configuration presets"><button data-ac-preset="practice">Solo practice</button><button data-ac-preset="kart">Kart session</button><button data-ac-preset="race">Race session</button></div><p class="field-hint">Presets set pit count and AI inclusion. Fine-tune every option below.</p><div class="ac-group"><h3>01 / Track identity</h3><div class="studio-fields"><label class="studio-field" data-existing="author">Creator</label><label class="studio-field" data-existing="country">Country</label></div><label class="studio-field" data-existing="city">City / venue</label><label class="studio-field">Mod folder / server track ID<input id="ac-track-id" maxlength="32" required pattern="[a-z][a-z0-9_]{0,31}" spellcheck="false" autocapitalize="off" autocomplete="off"></label><div class="analysis-actions"><button id="ac-copy-id" class="outline-button">Copy ID</button><button id="ac-new-id" class="outline-button">New unique ID</button></div><p class="field-hint">This ID stays the same when you rename your circuit. Use New unique ID for a separate mod or an existing-name conflict; install its new ZIP on server and clients.</p><button id="ac-edit-profile" class="outline-button">Edit name, description & version</button></div><div class="ac-group"><h3>02 / Paddock & starting grid</h3><div class="studio-fields"><label class="studio-field" data-existing="pits">Pit boxes · 1–16</label><label class="studio-field">Grid row spacing · m<input id="ac-gridSpacing" type="number" min="4" max="12" step=".5"></label></div><div class="gantry-controls"><label class="toggle-row"><span>Start/Finish Gantry</span><input id="ac-gantry" type="checkbox"><span class="toggle"></span></label><label class="studio-field">Clearance above the road · m<input id="ac-gantryClearance" type="number" min="4.5" max="8" step=".5"></label><p class="field-hint">A signed overhead gantry follows your start/finish line. Supports remain beside the racing road and span adjacent pit pavement.</p></div><p id="ac-pit-summary" class="field-hint"></p><button id="ac-design-pits" class="outline-button">Design pit lane ↗</button></div><div class="surface-slot"></div><div class="ac-group"><h3>04 / Include in mod</h3><div data-existing-toggle="kerbs"></div><div data-existing-toggle="barriers"></div><label class="studio-field">Outer boundary height · m<input id="ac-wallHeight" type="number" min=".5" max="4" step=".1"></label><label class="toggle-row"><span>Placed trees</span><input id="ac-trees" type="checkbox"><span class="toggle"></span></label><label class="toggle-row"><span>Placed buildings</span><input id="ac-buildings" type="checkbox"><span class="toggle"></span></label><div data-existing-toggle="ai"></div><label class="toggle-row"><span>Show ideal racing line</span><input id="ac-idealLine" type="checkbox"><span class="toggle"></span></label><div class="ideal-line-legend"><span>● Flow</span><span>● Corner</span><span>● Tight turn</span></div><p class="field-hint">A dashed, colored learning guide appears in the drawing, 3D and exported road. Includes guide AI even with the AI switch off. It is generated from your layout; refine it in-game for competitive racing.</p><p class="field-hint">Grass is always included. Custom barriers follow your drawing. Generated AI uses the racing guide when enabled, or the centerline otherwise.</p></div><div class="ac-group online-setup"><h3>05 / Online server</h3><p class="field-hint">Use the folder ID as TRACK. This circuit has no layout name: leave CONFIG_TRACK empty.</p><pre id="ac-server-config" aria-label="Server track configuration"></pre><div class="analysis-actions"><button id="ac-copy-server" class="outline-button">Copy server settings</button><button id="ac-server-zip" class="outline-button">Download server ZIP</button></div><p class="field-hint">The server ZIP contains track data and installation instructions. Use the full client ZIP if your manager requires a model or preview. Everyone must install the same client export. Replace matching revisions together, then restart or rescan the server.</p><p id="ac-server-status" class="field-hint" role="status"></p></div><div class="ac-ready"><b id="ac-ready-label"></b><p id="ac-ready-note"></p></div><div class="analysis-actions"><button id="ac-setup-preview" class="outline-button">Inspect in 3D</button><button id="ac-setup-export" class="outline-button">Review & export ZIP</button></div><p class="field-hint">Install the ZIP with Content Manager, select this track, then start a single-car Practice session. Pick weather in Content Manager.</p>`;
 for(const [key,input] of Object.entries(inputs)){const target=body.querySelector(`[data-existing="${key}"]`);if(target)target.append(input);else{const label=document.createElement('label');label.className='toggle-row';const span=document.createElement('span');span.textContent={kerbs:'Flat red & white kerbs',barriers:'Outer boundary barriers',ai:'Driving AI & pit AI'}[key];label.append(span,input);const toggle=document.createElement('span');toggle.className='toggle';label.append(toggle);body.querySelector(`[data-existing-toggle="${key}"]`).append(label);}}
 for(const key of ['gridSpacing','wallHeight','trees','buildings','gantry','gantryClearance','idealLine'])$('#ac-'+key).onchange=()=>{const input=$('#ac-'+key);if(!input.checkValidity()){api.toast('Use a value inside the range shown.');refresh();return;}api.updateTrack(t=>{t.export={...DEFAULT_EXPORT,...t.export,[key]:input.type==='checkbox'?input.checked:Number(input.value)};});};
 body.querySelectorAll('[data-ac-preset]').forEach(b=>b.onclick=()=>{const settings={practice:{pitboxes:1,ai:false},kart:{pitboxes:8,ai:true},race:{pitboxes:16,ai:true}}[b.dataset.acPreset];api.updateTrack(t=>t.export={...DEFAULT_EXPORT,...t.export,...settings});api.toast('Session setup applied. Review the pit lane in 3D.');});
 $('#ac-edit-profile').onclick=()=>$('#circuit-details-btn').click();$('#ac-design-pits').onclick=()=>api.showPanel('.pit-design-panel');$('#ac-setup-preview').onclick=()=>api.preview();$('#ac-setup-export').onclick=()=>$('#ac-export-btn').click();
 const copy=async text=>{try{await navigator.clipboard.writeText(text);api.toast('Copied.');}catch{api.toast('Copy is unavailable in this browser. Select the text and copy it manually.');}};
 $('#ac-copy-id').onclick=()=>copy(trackFolder(api.getTrack()));
 $('#ac-copy-server').onclick=()=>copy(serverConfig(api.getTrack()));
 $('#ac-track-id').onchange=()=>{const value=$('#ac-track-id').value.trim();if(!validTrackId(value)){api.toast('Use 1–32 lowercase letters, numbers or underscores, starting with a letter.');refresh();return;}api.updateTrack(t=>t.export={...DEFAULT_EXPORT,...t.export,trackId:value});};
 $('#ac-new-id').onclick=()=>{api.updateTrack(t=>t.export={...DEFAULT_EXPORT,...t.export,trackId:newTrackId(t.name)});api.toast('New mod identity created. Install its client and server ZIP together. Undo restores the old ID.');};
 $('#ac-server-zip').onclick=async()=>{const button=$('#ac-server-zip');button.disabled=true;$('#ac-server-status').textContent='Preparing matching server data…';try{await new Promise(requestAnimationFrame);const track=structuredClone(api.getTrack()),images=await exportImages(track),result=exportServerZip(track,images),url=URL.createObjectURL(new Blob([result.bytes],{type:'application/zip'})),a=document.createElement('a');a.href=url;a.download=result.slug+'_server.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);$('#ac-server-status').textContent='Downloaded. Read SERVER_INSTALL.txt and install the matching client ZIP for every driver.';}catch(error){$('#ac-server-status').textContent=error.message;}finally{refresh();}};
 function refresh(){const t=api.getTrack(),o={...DEFAULT_EXPORT,...t.export},plan=api.getPitPlan(),report=validateExport(t);$('#ac-folder').textContent=trackFolder(t);$('#ac-track-id').value=trackFolder(t);$('#ac-server-config').textContent=serverConfig(t);$('#ac-server-zip').disabled=report.errors.length>0;$('#ac-package-summary').textContent=`${o.pitboxes} slots · ${(GRASS[t.grass]||GRASS.mown).label} · ${o.buildings?(t.buildings||[]).length:0} buildings · ${o.trees?(t.trees||[]).length:0} trees`;for(const key of ['gridSpacing','wallHeight','trees','buildings','gantry','gantryClearance','idealLine']){const input=$('#ac-'+key);if(input.type==='checkbox')input.checked=o[key];else input.value=o[key];}$('#ac-wallHeight').disabled=!o.barriers;$('#ac-gantryClearance').disabled=!o.gantry;$('#ac-pit-summary').textContent=t.points.length<2?'Draw the circuit to generate a fitted pit route.':`${plan.count} fitted bays · ${Math.round(plan.length)} m pit route${plan.expanded?' · parking apron added':''}${plan.connected?' · track connected':''}`;$('#ac-ready-label').textContent=report.errors.length?'Finish your track':report.warnings.length?'Ready for review':'Ready to export';$('#ac-ready-note').textContent=report.errors[0]||`${report.warnings.length} review notes. Inspect spawns, pit connections, and scenery before installing.`;$('#ac-setup-export').disabled=report.errors.length>0;$('#ac-setup-preview').disabled=t.points.length<3;}
 return {refresh};}
